GAME = {
  tag = "Kraken's Krits & Fumbles 2E",
  pfx = "KKF2_",
  -- as in 1.0: a complication on a d6 of 5-6, else the plain crit or miss
  defaultCrit = "third",
  defaultFumble = "third",
}

local function has(s, words)
  for _, w in ipairs(words) do
    if s:find(w, 1, true) then return true end
  end
  return false
end
local NATURAL = { "bite", "claw", "fist", "gore", "horn", "tentacle", "slam", "kick", "talon", "sting", "tail", "butt", "hoof", "punch" }
local BLUDGEON = { "mace", "club", "hammer", "staff", "flail", "morning star", "morningstar", "maul" }
local PIERCE = { "spear", "dagger", "rapier", "lance", "pick", "javelin", "trident", "dart", "fork", "awl" }

function pickTable(sKind, rSource, rTarget, rRoll)
  local sDesc = ((rRoll and rRoll.sDesc) or ""):lower()
  local sName = sDesc:match("%]%s*([^%[]+)") or sDesc
  local sType
  if (rRoll and rRoll.sRange == "R") or sDesc:find("(r)", 1, true) then sType = "missile"
  elseif sName:match("^%s*$") or has(sName, NATURAL) then sType = "natural"
  elseif has(sName, BLUDGEON) then sType = "bludgeoning"
  elseif has(sName, PIERCE) then sType = "piercing"
  else sType = "slashing" end
  return ((sKind == "fumble") and "fumble" or "crit") .. sType
end

local function onAttackPostResolve(rSource, rTarget, rRoll)
  KrakenKrits.onAttackResult(rSource, rTarget, rRoll, rRoll and rRoll.sResult)
end

GAME.pickTable = pickTable
GAME.hook = function()
  -- 2E's own HRFC option rolls the module's "Fumble" / "Critical Hit" tables;
  -- while ours is on for that kind, ours does it (as 1.0 did)
  if ActionAttack and ActionAttack.notifyApplyHRFC then
    local fOrig = ActionAttack.notifyApplyHRFC
    ActionAttack.notifyApplyHRFC = function(sTable)
      local sOpt = OptionsManager.getOption(GAME.pfx .. ((sTable == "Fumble") and "FUMBLE" or "CRIT"))
      if sOpt == "off" then fOrig(sTable) end
    end
  end
  GameManager.addEventFunction("onAttackPostResolve", onAttackPostResolve)
end
